import json
import urllib.request
import csv
import io

# Re-examine all available proteins to find if there are smaller variants
req = urllib.request.Request(
    'https://www.fpbase.org/api/proteins/',
    headers={'User-Agent': 'Mozilla/5.0'}
)
with urllib.request.urlopen(req, timeout=10) as response:
    data = response.read().decode('utf-8')

reader = csv.DictReader(io.StringIO(data))
rows = list(reader)

# Get PDB IDs
with open('/app/pdb_ids.txt', 'r') as f:
    pdb_ids = set(line.strip().upper() for line in f)

# For each PDB ID, get all protein variants (there might be multiple)
all_variants = {}
for row in rows:
    pdb_list = [row.get(f'pdb.{i}', '').strip().upper() for i in range(20)]
    pdb_list = [p for p in pdb_list if p in pdb_ids]

    if pdb_list:
        seq = row.get('seq', '')
        if seq:
            seq_len = len(seq) - 1 if seq[0] == 'M' else len(seq)
            pdb = pdb_list[0]
            if pdb not in all_variants:
                all_variants[pdb] = []
            all_variants[pdb].append({
                'name': row.get('name', ''),
                'slug': row.get('slug', ''),
                'seq_len': seq_len,
                'seq': seq,
                'ex': float(row.get('states.0.ex_max', 0) or 0),
                'em': float(row.get('states.0.em_max', 0) or 0)
            })

# Find proteins that meet exact filter requirements
# MUST HAVE: ex=505nm donor, em=610nm acceptor
exact_505 = []
exact_610 = []

for pdb, variants in all_variants.items():
    for v in variants:
        if v['ex'] == 505.0:
            exact_505.append((pdb, v['name'], v['seq_len']))
        if v['em'] == 610.0:
            exact_610.append((pdb, v['name'], v['seq_len']))

print("=== PROTEINS WITH EXACT 505nm EXCITATION ===")
for pdb, name, size in exact_505:
    print(f"{pdb}: {name} - {size} aa")

print("\n=== PROTEINS WITH EXACT 610nm EMISSION ===")
for pdb, name, size in exact_610:
    print(f"{pdb}: {name} - {size} aa")

# Look for alternatives with very close values
print("\n=== ALTERNATIVE DONORS (500-510nm) ===")
donors_alt = []
for pdb, variants in all_variants.items():
    for v in variants:
        if 500 <= v['ex'] <= 510:
            donors_alt.append((pdb, v['name'], v['seq_len'], v['ex']))
donors_alt.sort(key=lambda x: (x[2], abs(x[3] - 505)))  # Sort by size, then distance from 505
for pdb, name, size, ex in donors_alt[:10]:
    print(f"{pdb}: {name} - {size} aa (ex={ex}nm)")

print("\n=== ALTERNATIVE ACCEPTORS (605-615nm) ===")
acceptors_alt = []
for pdb, variants in all_variants.items():
    for v in variants:
        if 605 <= v['em'] <= 615:
            acceptors_alt.append((pdb, v['name'], v['seq_len'], v['em']))
acceptors_alt.sort(key=lambda x: (x[2], abs(x[3] - 610)))
for pdb, name, size, em in acceptors_alt[:10]:
    print(f"{pdb}: {name} - {size} aa (em={em}nm)")

EOF
